  'on · the browser does not start: {problem}. Turn it off and on again: MADRE downloads what is missing.': 'encendido · el navegador no arranca: {problem}. Apágalo y vuelve a encenderlo: MADRE descarga lo que falte.',
  'Untitled': 'Sin título',
  'Files': 'Archivos',
  'The viewer': 'El visor',
  'The second conversation': 'El segundo chat',
  '{first} and {second} float over the conversation while there is no room beside it, and go back beside it when there is.': '{first} y {second} flotan sobre la conversación mientras no hay lugar a su lado, y regresan cuando lo hay.',
  '{what} floats over the conversation while there is no room beside it, and goes back beside it when there is.': '{what} flota sobre la conversación mientras no hay lugar a su lado, y regresa cuando lo hay.',
  '{what} moved to a window so the conversation stays readable. Its split button puts it back beside.': '{what} se abrió en una ventana aparte para que la conversación se lea bien. Su botón de pantalla dividida lo regresa al lado.',
  "I want to start a project here. Ask me three questions about what I want to achieve, and then propose the first three steps.": "Quiero empezar un proyecto aqu\u00ed. Hazme tres preguntas sobre lo que quiero lograr y luego prop\u00f3n los primeros tres pasos.",
  'Before writing anything, ask me what I want to build and propose a plan in steps.': 'Antes de escribir nada, pregúntame qué quiero construir y propón un plan por pasos.',
  'First conversation': 'Primer chat',
  'Fresh input tokens of a typical (median) turn with each outside tool (MCP) connected, and without it.': 'Tokens de entrada nuevos en una respuesta típica (la mediana), con cada herramienta externa (MCP) conectada y sin ella.',
  '@{agent} · {server}: {with} with it ({nWith} turns) · {without} without it ({nWithout} turns)': '@{agent} · {server}: {with} con él ({nWith} respuestas) · {without} sin él ({nWithout} respuestas)',
  'it did not answer within {seconds}s': 'no contestó en {seconds} s',
  'it exited with code {code} before it spoke': 'se cerró con el código {code} antes de responder',
  'TEST BROWSER stays off: MADRE downloaded the {browser} browser and it still does not start ({problem}). Check your internet connection and turn it on again, or choose another browser in its settings.':
    '«Navegador de pruebas» se queda apagado: MADRE descargó el navegador {browser} y aún no arranca ({problem}). Revisa tu conexión a internet y vuelve a encenderlo, o elige otro navegador en sus ajustes.',
  'TEST BROWSER stays off: MADRE could not install its browser server ({problem}). Check your internet connection and turn it on again.':
    '«Navegador de pruebas» se queda apagado: MADRE no pudo instalar su servidor de navegador ({problem}). Revisa tu conexión a internet y vuelve a encenderlo.',
  '#{n} {label} is written in the message: you will be asked to confirm it when you send it.': '«#{n} {label}» está escrito en el mensaje: se te pedirá confirmarlo al enviarlo.',
  'stopped at the {seconds}s limit': 'detenido al llegar al límite de {seconds} s',
  'stopped ({why})': 'detenido ({why})',
  'did not start': 'no arrancó',
  'exit {code}': 'salió con código {code}',
  'went fine': 'salió bien',
  'failed · code {code}': 'falló · código {code}',
  'halted': 'detenido',
