  'Files changed: {files}': 'Archivos cambiados: {files}',
  'running {command}': 'corría {command}',
  'MADRE is shutting down': 'MADRE se está cerrando',
  'Google says the AI Studio project behind this Gemini key has no prepaid credits left; every request is refused (HTTP 429) until it is topped up.':
    'Google dice que el proyecto de AI Studio asociado a esta llave de API de Gemini se quedó sin créditos prepagados; cada petición se rechaza (HTTP 429) hasta que se recargue.',
  'Add credits at https://ai.studio/projects, or switch the Gemini CLI to another key.':
    'Agrega créditos en https://ai.studio/projects, o cambia la app de Gemini a otra llave de API.',
  "Wait a minute, or pick an explicit model such as gemini-3-flash-preview to skip the router; check the key's quota at aistudio.google.com.":
    'Espera un minuto, o elige un modelo explícito como gemini-3-flash-preview para saltarte el enrutador; revisa el límite de tu plan en aistudio.google.com.',
  'Google reported the model as unavailable (HTTP 503) and the CLI kept retrying.':
    'Google reportó el modelo como no disponible (HTTP 503) y la app de Gemini siguió reintentando.',
  'Try again shortly or choose another model.': 'Vuelve a intentar en un momento o elige otro modelo.',
  ' · said it created {files}, but it is not in your project': ' · dijo que creó {files}, pero no está en tu proyecto',
  ' · nothing was written in this reply': ' · en esta respuesta no se escribió nada',
  'ASK AGAIN': 'Pedirlo otra vez',
  'Last time you said you created {files}, but nothing was written to disk. Create them now and check that they exist before you answer.': 'La vez pasada dijiste que creaste {files}, pero no se escribió nada. Créalos ahora y revisa que existan antes de contestar.',
  'Google rejected the Gemini credentials.': 'Google rechazó las credenciales de Gemini.',
  'Run `gemini` and use /auth, or check GEMINI_API_KEY.': 'Ejecuta `gemini` y usa /auth, o revisa GEMINI_API_KEY.',
  'Google no longer accepts this Gemini sign-in (IneligibleTierError): the free personal Google account is refused before it reaches a model.': 'Google ya no acepta este inicio de sesión de Gemini (IneligibleTierError): rechaza la cuenta personal gratuita de Google antes de llegar al modelo.',
  'Paste a Gemini API key from Google AI Studio in Settings › Agents › Gemini, or run `gemini`, type /auth and pick "Use Gemini API key".': 'Pega una llave de API de Gemini de Google AI Studio en Ajustes › Tus IAs › Gemini, o ejecuta `gemini`, escribe /auth y elige «Use Gemini API key».',

