  'Your {device} is connected.': 'Tu {device} está conectado.',
  'On the phone, add MADRE to the home screen to open it like an app. Your projects are there whenever this Mac is awake and on this Wi-Fi.': 'En el teléfono, agrega MADRE a la pantalla de inicio para abrirla como una app. Tus proyectos están ahí siempre que esta Mac esté despierta y en este Wi-Fi.',
