  'Home and every open project start again': 'Inicio y los proyectos abiertos arrancan de nuevo',
  'Restart MADRE?': '¿Reiniciar MADRE?',
  'Home closes.': 'Inicio se cierra.',
  'Home closes and opens again.': 'Inicio se cierra y vuelve a abrir.',
  'Home and every open project close and open again.': 'Inicio y todos los proyectos abiertos se cierran y vuelven a abrir.',
  'Home and the one open project close and open again.': 'Inicio y el proyecto abierto se cierran y vuelven a abrir.',
  'Home and the {n} open projects close and open again.': 'Inicio y los {n} proyectos abiertos se cierran y vuelven a abrir.',
  'It takes a few seconds. Every page you have open comes back on its own.': 'Tarda unos segundos. Cada página que tengas abierta vuelve sola.',
  'Home and your projects close and open again on the same addresses.': 'Inicio y tus proyectos se cierran y vuelven a abrir en las mismas direcciones.',
  'MADRE is taking longer than usual. Open it the way you always do; your projects, conversations and settings are there.': 'MADRE está tardando más de lo normal. Ábrela como siempre; tus proyectos, conversaciones y ajustes siguen ahí.',
  'MADRE is restarted from its own page, on this computer.': 'MADRE se reinicia desde su propia página, en esta computadora.',
  'Home and every open project close': 'Se cierran Inicio y los proyectos abiertos',
