  // The lobby, second round (2026-10-10): MADRE's summary, recent decisions, what needs you.
  'Recent summary': 'Resumen reciente',
  'Summarize again': 'Resumir de nuevo',
  'Reading your conversations…': 'Leyendo tus chats…',
  'No conversations in the last two weeks. What you work on in any project shows here, summarised by MADRE.': 'No hay chats en las últimas dos semanas. Lo que trabajes en cualquier proyecto aparece aquí, resumido por MADRE.',
  'MADRE is summarising your latest conversations…': 'MADRE está resumiendo tus últimos chats…',
  'MADRE\'s local model is off: this is the last summary it wrote.': 'La IA local está apagada: este es el último resumen que escribió.',
  'MADRE\'s local model is off: these are your latest conversations, as they are.': 'La IA local está apagada: estos son tus últimos chats, tal cual.',
  'The AI on this computer is small to summarise them well: these are your latest conversations, as they are.': 'La IA local es muy pequeña para resumirlos bien: estos son tus últimos chats, tal cual.',
  'MADRE could not summarise them this time: these are your latest conversations, as they are.': 'MADRE no pudo resumirlos esta vez: estos son tus últimos chats, tal cual.',
  'There is newer work than this summary: it updates itself in a few minutes, or now if you press Summarize again.': 'Hay trabajo más reciente que este resumen: se actualiza solo en unos minutos, o ahora si tocas «Resumir de nuevo».',
  'Written by MADRE on this Mac from your latest conversations.': 'Escrito por MADRE en esta Mac a partir de tus últimos chats.',
  'Recent decisions': 'Decisiones recientes',
  'Reading the open projects…': 'Leyendo los proyectos abiertos…',
  'No decisions yet in the open projects. When an archive keeps one, it shows here.': 'Todavía no hay decisiones en los proyectos abiertos. Cuando la memoria de un proyecto guarde una, aparece aquí.',
  'Needs you': 'Te necesita',
  'All in order.': 'Todo en orden.',
  "Nothing needs you right now.": "Nada te necesita por ahora.",
  '{room} runs an older MADRE.': '{room} usa una versión anterior de MADRE.',
  'Update it to see it here and to connect it.': 'Actualízalo para verlo aquí y para conectarlo.',
