  'It may be busy. If it stays like this, close it and open it again.': 'Quizá está ocupado. Si sigue así, ciérralo y ábrelo de nuevo.',
  'Connected once, every project uses it.': 'Se conecta una vez y todos los proyectos lo usan.',
