  'Its agents can look the notes up when they need them.': 'Sus IAs pueden consultar las notas cuando las necesiten.',
  // The Macroverse with BISHOP at its centre (2026-10-10).
  'Drag the space to move it · wheel to come closer · click a project to look at it · drag it to turn it · carry one onto the Coordinator for the Coordinator to read it, or onto another to connect them · ← → from one to the next · Esc to come back': 'Arrastra el espacio para moverlo · rueda para acercarte · clic en un proyecto para verlo · arrástralo para girarlo · llévalo al Coordinador para que lo consulte, o a otro para conectarlos · ← → de uno a otro · Esc para volver',
