  'Keys are written where OpenCode reads them (~/.local/share/opencode/auth.json), readable only by you; MADRE keeps no copy. The rest is saved to ~/.pulse/config.json.': 'Las llaves de API se guardan donde OpenCode las lee (~/.local/share/opencode/auth.json) y solo tú puedes leerlas; MADRE no guarda copia. El resto de la configuración se guarda en ~/.pulse/config.json.',
