  // IA local por proyecto (src/local-ai.mjs): Inicio elige qué proyectos usan Ollama.
  'Say on or off.': 'Indica si se enciende o se apaga.',
  'The Coordinator follows the local AI switch of Modules.': 'El Coordinador sigue el interruptor de IA local de Módulos.',
  'Home turns the local AI on in every project. Change it in Home › Settings › Local AI.': 'Inicio enciende la IA local en todos los proyectos. Cámbialo en Inicio › Ajustes › IA local.',
  'off in this project · Home › Settings › Local AI': 'apagada en este proyecto · Inicio › Ajustes › IA local',
  'Local AI is off for every project.': 'La IA local está apagada para todos los proyectos.',
  'In this project': 'En este proyecto',
  'One by one': 'Uno a uno',
  'Manual': 'Manual',
  '{n} of {total} projects': '{n} de {total} proyectos',
  'Ollama is not running': 'Ollama no está encendido',
  'Every project uses it, new ones too.': 'Todos los proyectos la usan, también los nuevos.',
  'Only the projects you switch on below. New projects start without it.': 'Solo los proyectos que enciendas abajo. Los proyectos nuevos empiezan sin ella.',
  'Home did not answer.': 'Inicio no respondió.',
  'Another download is running. When it ends, try this one.': 'Hay otra descarga en curso. Cuando termine, prueba esta.',
  'MADRE did not answer. Check that it is still open.': 'MADRE no respondió. Revisa que siga abierto.',
  'MADRE could not prepare the folder where @{agent} writes, so nothing was started: {error}': 'MADRE no pudo preparar la carpeta donde escribe @{agent}, así que no se empezó nada: {error}',
  '<the briefing above>': '<el documento de arriba>',
  '<written for this turn, deleted after it>': '<escrita para este turno, borrada después>',
  'MADRE has no adapter for @{agent}.': 'MADRE no tiene adaptador para @{agent}.',
  '--ephemeral: the run keeps no session of its own, so nothing said here reaches another project.': '--ephemeral: la ejecución no guarda una sesión propia, así que nada de lo dicho aquí llega a otro proyecto.',
  '--no-session-persistence: the run keeps no session of its own.': '--no-session-persistence: la ejecución no guarda una sesión propia.',
  'Only the project\'s own CLAUDE.md and MADRE\'s briefing are read; hooks, plugins and outside MCP servers are not.': 'Solo se leen el CLAUDE.md del proyecto y el documento de MADRE; los hooks, los plugins y los servidores MCP de fuera, no.',
  'GEMINI_CLI_HOME points at a temporary home made for this turn and removed after it, so settings, hooks and extensions come from there and not from yours.': 'GEMINI_CLI_HOME apunta a una carpeta de inicio temporal hecha para este turno y borrada después, así que los ajustes, hooks y extensiones salen de ahí y no de los tuyos.',
  'GEMINI_CLI_NO_RELAUNCH keeps the launcher from spawning a second process MADRE could not stop.': 'GEMINI_CLI_NO_RELAUNCH evita que el lanzador abra un segundo proceso que MADRE no podría detener.',
  'The run is given the model you chose and nothing else of your session.': 'La ejecución recibe el modelo que elegiste y nada más de tu sesión.',
  '#0 and #1: --mode ask, Cursor\'s read-only mode, whatever its own settings say; no edits and no commands. #2 and #3: its agent mode with --force, writing allowed and every command denied. #4: commands allowed too. The places nobody writes stay denied at every mode, and MADRE locks and puts them back itself.': '#0 y #1: --mode ask, el modo de solo lectura de Cursor, digan lo que digan sus ajustes; sin ediciones ni comandos. #2 y #3: su modo agente con --force, con escritura permitida y todos los comandos negados. #4: también comandos. Los lugares donde nadie escribe siguen negados en todos los modos, y MADRE los bloquea y los repone.',
  'CURSOR_CONFIG_DIR points at a configuration made for this turn and removed after it, with only what the mode you chose allows. The sign-in stays in the system keychain.': 'CURSOR_CONFIG_DIR apunta a una configuración hecha para este turno y borrada después, con solo lo que permite el modo que elegiste. La sesión se queda en el llavero del sistema.',
  'the temporary home for this turn': 'la carpeta de inicio temporal de este turno',
  'so the launcher stays killable': 'para que el lanzador se pueda detener',
  'the configuration for this turn, from the mode you chose': 'la configuración de este turno, según el modo que elegiste',
  'a turn never opens a page': 'un turno nunca abre una página',
  'This computer does not have git, which MADRE needs to take the restore point before @{agent} writes, so nothing was changed. Install git and send it again.': 'Esta computadora no tiene git, que MADRE necesita para tomar el punto de restauración antes de que @{agent} escriba, así que no se cambió nada. Instala git y vuelve a enviarlo.',
  'This computer does not have git, which MADRE needs to take the restore point before an AI writes. Install git and reload this page.': 'Esta computadora no tiene git, que MADRE necesita para tomar el punto de restauración antes de que una IA escriba. Instala git y vuelve a cargar esta página.',
  'NEEDS GIT': 'FALTA GIT',
  'MADRE could not take the restore point before @{agent} writes, so nothing was changed: {error}': 'MADRE no pudo tomar el punto de restauración antes de que @{agent} escriba, así que no se cambió nada: {error}',
  'Reload and settings': 'Recargar y ajustes',
  '{names} will use it when restarted: it was started before this setting existed.': '{names} tomará el cambio al reiniciarse: se abrió antes de que existiera este ajuste.',
  'Ollama runs local AI: it searches and sums up each project\'s memory and answers as @madre, free and private. Choose which projects use it.': 'La IA local vive en esta computadora gracias a Ollama: busca y resume la memoria de cada proyecto y contesta como @madre, gratis y en privado. Elige qué proyectos la usan.',
  'Which projects': 'Qué proyectos',
  'Mode': 'Modo',
  'All of them use it. Choose «One by one» or «Manual» to turn some off.': 'Todos la usan. Elige «Uno a uno» o «Manual» para apagarla en algunos.',
  'A switch here is the same one the project shows in its Settings.': 'Cada interruptor es el mismo que el proyecto muestra en sus Ajustes.',
  'No projects yet': 'Todavía no hay proyectos',
  'Open · using it': 'Abierto · la usa',
