  'Notes is off in this project. Turn it on in Modules.': 'Notas está apagado en este proyecto. Enciéndelo en Módulos.',
  '{n} notes in this project': '{n} notas en este proyecto',
  'That note is no longer here.': 'Esa nota ya no está.',
  'This project already has {n} notes. Delete one to make room.': 'Este proyecto ya tiene {n} notas. Elimina una para hacer espacio.',
  'Colored notes on your project': 'Notas de colores en tu proyecto',
  'Write what you want to keep in sight on notes of six colors, each in a window you move and size as you like. Only you read them: no agent sees them and nothing leaves your computer.': 'Escribe lo que quieras tener a la vista en notas de seis colores, cada una en una ventana que mueves y ajustas a tu gusto. Solo tú las lees: ningún agente las ve y nada sale de tu computadora.',
  'Colored notes on the project, each in a window you move and size as you like. Only you read them: no agent sees them and nothing leaves your computer.': 'Notas de colores en el proyecto, cada una en una ventana que mueves y ajustas a tu gusto. Solo tú las lees: ningún agente las ve y nada sale de tu computadora.',
  'Idea by {name}': 'Idea de {name}',
  'Thank you for building MADRE with us.': 'Gracias por construir MADRE con nosotros.',
