  'Coming up': 'Próximos',
  '{n} in this project. Home shows them for every project.': '{n} en este proyecto. Inicio los muestra de todos los proyectos.',
  'None yet. When you write something you still have to do, a card offers the reminder.': 'Aún no hay ninguno. Cuando escribas algo que tengas pendiente, una tarjeta te ofrecerá el recordatorio.',
  'Turn it on and a card offers a reminder when you write something you still have to do.': 'Enciéndelo y, cuando escribas algo que tengas pendiente, una tarjeta te ofrecerá el recordatorio.',
  'Delete': 'Eliminar',
  'A reminder is due: {what}': 'Tienes un recordatorio: {what}',
  '{n} reminders are due. They are in «Needs you».': 'Tienes {n} recordatorios. Están en «Te necesita».',
  '{n} reminders ahead': '{n} recordatorios por venir',
  'Write what to remember.': 'Escribe qué hay que recordar.',
  'That offer is not known.': 'Esa oferta no existe.',
  'Say when.': 'Di cuándo.',
  'That reminder is no longer here.': 'Ese recordatorio ya no está.',
  'What you still have to do, remembered': 'Lo que tienes pendiente, recordado',
  'When you write something you still have to do, or ask for the same thing every day, a card offers to remind you, with the time already chosen: one press. When it is due, Home tells you, and so does the project it came from. Read on your computer; no agent is asked. An idea by Daniel Castillo.': 'Cuando escribes algo que tienes pendiente, o pides lo mismo todos los días, una tarjeta te ofrece recordártelo con la hora ya elegida: un clic. Cuando llega la hora, te avisa Inicio y también el proyecto de donde salió. Se lee en tu computadora; no se le pregunta a ningún agente. Una idea de Daniel Castillo.',
  'Notices what you say you still have to do, or what you ask for every day, and offers to remind you with one press. Reminders show in Home and in the project they came from. Read on your computer, with the local AI when you have it; no agent is asked.': 'Nota lo que dices que tienes pendiente, o lo que pides todos los días, y te ofrece recordártelo con un clic. Los recordatorios aparecen en Inicio y en el proyecto de donde salieron. Se lee en tu computadora, con la IA local cuando la tienes; no se le pregunta a ningún agente.',
  'a notes.json file beside the project’s conversations, in ~/.pulse': 'un archivo notes.json junto a las conversaciones del proyecto, en ~/.pulse',
  'a reminders.json file in ~/.pulse, one for the whole computer': 'un archivo reminders.json en ~/.pulse, uno para toda la computadora',
  'turn off Notes': 'apagar Notas',
  'turn on Notes': 'encender Notas',
  'turn off Reminders': 'apagar Recordatorios',
  'turn on Reminders': 'encender Recordatorios',
  'In {n} hours': 'En {n} horas',
  'In {n} minutes': 'En {n} minutos',
  'Move it': 'Moverlo',
  'Move…': 'Mover…',
  'Due': 'Vencido',
  'Overdue': 'Vencidos',
  'Clear': 'Vaciar',
  'The last ones you marked done in this project.': 'Los últimos que marcaste como hechos en este proyecto.',
  'Again tomorrow': 'Otra vez mañana',
