  'Developer': 'Desarrollador',
  'Community': 'Comunidad',
  'The entry is missing: entrada.json, beside the module.': 'Falta la entrada: entrada.json, junto al módulo.',
  'id: lowercase letters, numbers and dashes, 2 to 40, starting with a letter.': 'id: minúsculas, números y guiones, de 2 a 40, empezando con letra.',
  'id: the entry says "{entry}" and the module says "{module}".': 'id: la entrada dice "{entry}" y el módulo dice "{module}".',
  'version: like 1.0.0.': 'versión: como 1.0.0.',
  'version: the entry says {entry} and the module says {module}.': 'versión: la entrada dice {entry} y el módulo dice {module}.',
  'nothing': 'nada',
  'name: in Spanish and English (es, en), up to 60 characters each.': 'nombre: en español y en inglés (es, en), hasta 60 caracteres cada uno.',
  'line: what it does in one line, in Spanish and English, up to 140 characters.': 'línea: qué hace en una línea, en español y en inglés, hasta 140 caracteres.',
  'summary: what it does and when to use it, in Spanish and English, up to 1200 characters.': 'resumen: qué hace y cuándo usarlo, en español y en inglés, hasta 1200 caracteres.',
  'shelf: one of {list}.': 'estante: uno de {list}.',
  'price: community modules are free for now (0).': 'precio: por ahora los módulos de la comunidad son gratis (0).',
  'minMadre: the oldest MADRE it works with, like 1.1.0.': 'minMadre: la MADRE más antigua con la que funciona, como 1.1.0.',
  'author: { "name": your name, "github": your GitHub user }.': 'autor: { "name": tu nombre, "github": tu usuario de GitHub }.',
  'spdx: the license of its code, one of {list}.': 'spdx: la licencia de su código, una de {list}.',
  'changes: what changed in this version, in Spanish and English, up to 400 characters.': 'cambios: qué cambió en esta versión, en español y en inglés, hasta 400 caracteres.',
  'hue: two colors like ["#60a5fa", "#1d4ed8"].': 'tono: dos colores como ["#60a5fa", "#1d4ed8"].',
  'icon: the shapes of a 20×20 drawing, up to 8000 characters.': 'ícono: las formas de un dibujo de 20×20, hasta 8000 caracteres.',
  'icon: only shapes; no scripts, events or links.': 'ícono: solo formas; sin scripts, eventos ni enlaces.',
  'The module does not load as MADRE loads one: {error}': 'El módulo no carga como MADRE carga uno: {error}',
  'It talks to the network but declares no `reaches`: say where it goes and why.': 'Habla con la red pero no declara `reaches`: di a dónde va y para qué.',
