  'By **{name}** (@{github}) · {license} · shelf `{shelf}`': 'De **{name}** (@{github}) · {license} · estante `{shelf}`',
  'no license': 'sin licencia',
  'To fix before it can be reviewed': 'Por corregir antes de revisarlo',
  'What it declares': 'Lo que declara',
  'yes': 'sí',
  'no': 'no',
  'Reaches: {list}': 'Se conecta a: {list}',
  'Keys it asks for: {list}': 'Llaves que pide: {list}',
  'Tools for the agents: {tools} · reads the conversations: {reads} · pages: {pages} · writes in the project: {writes}': 'Herramientas para los agentes: {tools} · lee las conversaciones: {reads} · páginas: {pages} · escribe en el proyecto: {writes}',
  'Commands: {list}': 'Comandos: {list}',
  'What its code reaches for': 'A qué llega su código',
  'Nothing beyond what MADRE hands every module.': 'Nada más allá de lo que MADRE le da a todo módulo.',
  'Fields MADRE does not know: {list}': 'Campos que MADRE no conoce: {list}',
  'Checked by MADRE (src/market-check.mjs). A person still reads the code before it is signed: an installed module runs in a separate process, but Node cannot guarantee containment of malicious code.': 'Revisado por MADRE (src/market-check.mjs). Una persona lee el código antes de firmarlo: un módulo instalado se ejecuta en un proceso aparte, pero Node no garantiza contener código malicioso.',
  'Only a module you made can be sent to the Market.': 'Solo un módulo hecho por ti se puede enviar al Mercado.',
  '{name} came from the Market: its author sends its new versions.': '{name} vino del Mercado: sus versiones nuevas las envía su autor.',
  'The file of {name} is no longer where it was.': 'El archivo de {name} ya no está donde estaba.',
  'Fix what is marked first.': 'Primero corrige lo que está marcado.',
  'Prepare': 'Preparar',
  'Send to the Market': 'Enviar al Mercado',
  // Habilidades (2026-11-08, H-1): lo que MADRE dice cuando lee una.
  'A skill starts with its header between two «---» lines: id, name and when it is for.': 'Una habilidad empieza con su cabecera entre dos líneas «---»: id, nombre y para cuándo es.',
  '«{id}» is not a name MADRE can use for a skill: lowercase letters, numbers and dashes, 2 to 40, starting with a letter.': '«{id}» no es un nombre que MADRE pueda usar para una habilidad: minúsculas, números y guiones, de 2 a 40, empezando por una letra.',
  'The skill says nothing: under the header go the instructions the agents will read.': 'La habilidad no dice nada: debajo de la cabecera van las instrucciones que leerán los agentes.',
  'The skill is too long ({has} characters, at most {max}). What does not fit goes in referencias/, and the instructions point at it: the agent reads it when it needs it.': 'La habilidad es muy larga ({has} caracteres, y caben {max}). Lo que no quepa va en referencias/ y las instrucciones lo señalan: el agente lo lee cuando lo necesita.',
  '{file} is a link, and a skill carries only its own files.': '{file} es un enlace, y una habilidad solo lleva sus propios archivos.',
  '{file} is outside the skill\'s folder.': '{file} está fuera de la carpeta de la habilidad.',
  'A skill carries at most {max} files.': 'Una habilidad lleva {max} archivos como máximo.',
  'A skill sent to the Market carries at most {max} files.': 'Una habilidad que se manda al Mercado lleva {max} archivos como máximo.',
  'A skill weighs at most {max} KB.': 'Una habilidad pesa {max} KB como máximo.',
  '{folder} has no {file}.': '{folder} no tiene {file}.',
  'A skill needs its {file}.': 'Una habilidad necesita su {file}.',
  '{file} is not a path a skill may carry.': '{file} no es una ruta que una habilidad pueda llevar.',
  'No skill «{id}».': 'No hay ninguna habilidad «{id}».',
  'A skill is off, matched or always on; nothing else.': 'Una habilidad está apagada, por relevancia o siempre encendida; nada más.',
  // Habilidades en el tablero (H-3).
  'Skills': 'Habilidades',
  'Ways of working you keep, handed to whichever agent answers. They tell your agents how you work; they never give them permission.': 'Formas de trabajar que guardas, entregadas al agente que responda, sea cual sea. Le dicen a tus agentes cómo trabajas; nunca les dan permiso.',
  'When this skill comes in': 'Cuándo entra esta habilidad',
  'What it says': 'Qué dice',
  'What it tells your agents': 'Qué le dice a tus agentes',
  'It comes in when:': 'Entra cuando:',
  'It has no sentence saying when it fits, so it only ever comes in switched on.': 'No dice en qué casos sirve, así que solo entra si la dejas encendida.',
  'It carries: {list}': 'Lleva: {list}',
  'It carries programs: {list}': 'Lleva programas: {list}',
  'MADRE never runs one. Only an agent can, and only in #4 AIRLOCK: in every other mode they do nothing. Read one before you open that mode.': 'MADRE nunca ejecuta ninguno. Solo puede un agente, y solo en #4 AIRLOCK: en cualquier otro modo no hacen nada. Léelos antes de abrir ese modo.',
  'this project only': 'solo en este proyecto',
  '{n} program(s)': '{n} programa(s)',
