  'Folder': 'Carpeta',
  'In every other project: {state}': 'En los demás proyectos: {state}',
  'Use it everywhere': 'Igual en todos',
  'Remove {name}?': '¿Quitar {name}?',
  'Its folder {dir} is deleted. What it told your agents stops reaching them. Nothing a program of its own may have written elsewhere is touched.': 'Se borra su carpeta {dir}. Lo que le decía a tus agentes deja de llegarles. No se toca nada que un programa suyo haya escrito en otra parte.',
  '{name} could not be changed.': 'No se pudo cambiar {name}.',
