  'Let the local AI read it first': 'Que la IA local lo lea primero',
  'When the project has it, it drops what is not a task and says it shorter. Without it, your own words are offered.': 'Si el proyecto la tiene, descarta lo que no es una tarea y lo dice más corto. Sin ella, se ofrecen tus propias palabras.',
