  '{value} of {need} weeks growing in a row': '{value} de {need} semanas seguidas creciendo',
  'Where people are lost': 'Dónde se pierde la gente',
  'Setting up an AI: only {pct} of new copies get one ready. The way to a first AI is the leak to fix first.': 'Al dejar lista una IA: solo {pct} de las copias nuevas lo logran. El camino a la primera IA es el hueco que hay que arreglar primero.',
  'Opening a project: {n} of {total} copies never opened one. Without a project there is nothing to ask; the way to a first project is the leak to fix first.': 'Al abrir un proyecto: {n} de {total} copias nunca abrieron uno. Sin proyecto no hay a quién preguntarle; el camino al primer proyecto es el hueco que hay que arreglar primero.',
  'The first question: {pct} of the copies with an AI ready never asked it anything.': 'En la primera pregunta: {pct} de las copias con una IA lista nunca le pidieron nada.',
  'Coming back: only {pct} return after the first day.': 'Al volver: solo {pct} regresan después del primer día.',
  'Habit: only {pct} used an AI on two days or more.': 'En el hábito: solo {pct} usaron una IA en dos días o más.',
  'Product or reach': 'Producto o difusión',
  'Product first: {used} of new copies ask an AI something and {d1} come back. More visitors now would only fill the leak.': 'Producto primero: {used} de las copias nuevas le piden algo a una IA y {d1} vuelven. Más visitas ahora solo llenarían el hueco.',
  'Reach: new copies use it and come back, but the week did not grow. Time to tell more people.': 'Difusión: las copias nuevas la usan y vuelven, pero la semana no creció. Toca contárselo a más gente.',
  'Both hold: copies use it, come back and the week grows.': 'Las dos van bien: las copias la usan, vuelven y la semana crece.',
  'Windows and the native app': 'Windows y la app nativa',
  '{share} of new copies come from Windows, and {win} of them ask an AI (the rest, {rest}). Windows is the main door: the native app weighs on the course.': '{share} de las copias nuevas vienen de Windows, y {win} de ellas le piden algo a una IA (las demás, {rest}). Windows es la puerta principal: la app nativa pesa en el rumbo.',
  '{share} of new copies come from Windows ({win} ask an AI; the rest, {rest}).': '{share} de las copias nuevas vienen de Windows ({win} le piden algo a una IA; las demás, {rest}).',
  'Windows is {share} of new copies: not the main door yet.': 'Windows es {share} de las copias nuevas: todavía no es la puerta principal.',
  'Charging for MADRE Pro': 'Cobrar MADRE Pro',
  'The four bars are met: there is a base to charge for Pro.': 'Las cuatro metas se cumplen: hay base para cobrar Pro.',
  '{met} of 4 bars met.': '{met} de 4 metas cumplidas.',
  'Not yet: {met} of 4 bars met.': 'Todavía no: {met} de 4 metas cumplidas.',
  'Traction to show': 'Tracción para mostrar',
  'Growing week after week with people who stay: there is traction to show.': 'Crece semana tras semana con gente que se queda: hay tracción para mostrar.',
  'It takes two weeks with diagnostics to tell whether it grows week after week.': 'Hacen falta dos semanas con diagnóstico para saber si crece semana tras semana.',
  '{met} of 3 bars met.': '{met} de 3 metas cumplidas.',
  'Not yet: {met} of 3 bars met.': 'Todavía no: {met} de 3 metas cumplidas.',
  '{share} of copies speak English: worth building for it.': '{share} de las copias hablan inglés: vale la pena construir para ese público.',
  '{share} of copies speak English: keep it working, Spanish leads.': '{share} de las copias hablan inglés: mantenerlo funcionando; el español manda.',
  '{share} of copies speak English: Spanish is where MADRE is used.': '{share} de las copias hablan inglés: MADRE se usa en español.',
  'Failures': 'Fallas',
  '{share} of copies met a failure ({k} of {n}): fix before spreading MADRE further.': '{share} de las copias tuvieron una falla ({k} de {n}): arreglar antes de difundir más a MADRE.',
  '{share} of copies met a failure ({k} of {n}): keep an eye on MADRE errors.': '{share} de las copias tuvieron una falla ({k} de {n}): vigilar «Errores de MADRE».',
  '{share} of copies met a failure: it holds up.': '{share} de las copias tuvieron una falla: aguanta bien.',
