  'Stars each day since the first': 'Estrellas de cada día desde la primera',
  'stars each day': 'estrellas de cada día',
  'never': 'nunca',
  'Read: madre.run {a} · GitHub {b} · npm {c}': 'Leído: madre.run {a} · GitHub {b} · npm {c}',
  'madre.run does not give the funnel yet (it answered {status}): publish the site so it has /api/rumbo.': 'madre.run todavía no da el embudo (respondió {status}): publica el sitio para que tenga /api/rumbo.',
  'madre.run did not answer just now: these are its last figures.': 'madre.run no respondió hace un momento: estos son sus últimos números.',
  'GitHub is read with your gh session: sign in with gh auth login to see stars and visits.': 'GitHub se lee con tu sesión de gh: entra con gh auth login para ver estrellas y visitas.',
  'MADRE\'s course': 'Rumbo de MADRE',
  'The variables that decide where MADRE goes: from a visit to a habit, what the numbers decide, and GitHub and npm. Only you see this.': 'Las variables que deciden a dónde va MADRE: de una visita a un hábito, lo que deciden los números, y GitHub y npm. Solo tú lo ves.',
  'The model of what decides MADRE\'s course: the funnel from a GitHub visit to using it on two days, with its leak in red; what the numbers say about product or reach, Windows, Pro, traction, English and failures; and every variable with how sure it is. It reads itself again on its own.': 'El modelo de lo que decide el rumbo de MADRE: el embudo de una visita en GitHub a usarla en dos días, con su hueco en rojo; lo que dicen los números sobre producto o difusión, Windows, Pro, tracción, inglés y fallas; y cada variable con qué tan seguro es su número. Se vuelve a leer solo.',
  'Add credits at https://ai.studio/projects, or paste another Gemini key in Settings › Agents › Gemini.': 'Agrega créditos en https://ai.studio/projects, o pega otra llave de Gemini en Ajustes › Tus IAs › Gemini.',
  'Wait a minute, or pick another model; check the key\'s quota at aistudio.google.com.': 'Espera un minuto o elige otro modelo; revisa la cuota de la llave en aistudio.google.com.',
  'Paste the key again in Settings › Agents › Gemini, or check GEMINI_API_KEY in your environment or ~/.gemini/.env.': 'Vuelve a pegar la llave en Ajustes › Tus IAs › Gemini, o revisa GEMINI_API_KEY en tu entorno o en ~/.gemini/.env.',
  'The message is longer than this Gemini model takes in one go.': 'El mensaje es más largo de lo que este modelo de Gemini recibe de una vez.',
  'Start a new conversation, or attach less text.': 'Empieza una conversación nueva o adjunta menos texto.',
  'Pick another model under the box.': 'Elige otro modelo debajo de la caja.',
  'MADRE could not reach Google\'s Gemini API: {reason}. Check this computer\'s internet connection.': 'MADRE no pudo llegar a la API de Gemini de Google: {reason}. Revisa la conexión a internet de esta computadora.',
  'Google\'s Gemini API refused to answer this message ({reason}).': 'La API de Gemini de Google se negó a contestar este mensaje ({reason}).',
  'Rephrase it, or ask another agent.': 'Dilo de otra forma o pregúntale a otro agente.',
  'Google did not accept this Gemini key (HTTP {status}): check you copied all of it, or make a new one at aistudio.google.com/app/apikey. Nothing was changed.': 'Google no aceptó esta llave de Gemini (HTTP {status}): revisa que la copiaste completa o crea una nueva en aistudio.google.com/app/apikey. No se cambió nada.',
  'No process is started for @gemini: the Gemini CLI is not installed, so MADRE sends the briefing to Google\'s Gemini API with your key and shows the answer. It cannot read the project, see attachments or write; install the Gemini CLI for that.': 'Para @gemini no se abre ningún proceso: el CLI de Gemini no está instalado, así que MADRE manda el informe a la API de Gemini de Google con tu llave y muestra la respuesta. No puede leer el proyecto, ver adjuntos ni escribir; para eso instala el CLI de Gemini.',
  'Install the Gemini CLI': 'Instalar el CLI de Gemini',
  'Answers through Google\'s API with your key: it does not read your projects or write in them. Install the Gemini CLI for that.': 'Contesta por la API de Google con tu llave: no lee tus proyectos ni escribe en ellos. Para eso instala el CLI de Gemini.',
  'Google · Gemini, through its API': 'Google · Gemini, por su API',
  'The briefing — the document above, your question, the memories it summoned and the transcript it carries — with your Gemini API key, to be answered by the model you chose.': 'El informe —el documento de arriba, tu pregunta, los recuerdos que trajo y la conversación que lleva— con tu llave de API de Gemini, para que lo conteste el modelo que elegiste.',
  'every turn you send to @gemini while Gemini answers through its API (a Gemini key and no Gemini CLI)': 'cada turno que le mandas a @gemini mientras Gemini contesta por su API (una llave de Gemini y sin el CLI de Gemini)',
  'you choose it every time you send a turn to @gemini; installing the Gemini CLI hands its turns back to the CLI': 'lo eliges cada vez que le mandas un turno a @gemini; al instalar el CLI de Gemini, sus turnos vuelven al CLI',
  'Answers through the provider\'s API: it does not read the project or attachments, and writes nothing. Install the CLI for the rest.': 'Contesta por la API del proveedor: no lee el proyecto ni los adjuntos, y no escribe nada. Para lo demás, instala el CLI.',
  'Ollama\'s model server did not answer (an error on its side). It is not your connection: try again in a few minutes; what already arrived stays.': 'El servidor de modelos de Ollama no contestó (un error de su lado). No es tu conexión: vuelve a intentarlo en unos minutos; lo que ya llegó se queda.',
  'That restore point is not known to this project.': 'Este proyecto no conoce ese punto de restauración.',
  'That EDIT turn is still running: press STOP ALL first.': 'Esa respuesta con «Puede editar» sigue en curso: pulsa primero «Detener todo».',
  'Project restored to the restore point taken before `{command}`: {restored} file(s) restored, {removed} removed.': 'Proyecto restaurado al punto de restauración de antes de `{command}`: {restored} archivo(s) restaurado(s), {removed} quitado(s).',
  'Project restored to the restore point taken before @{agent}\'s EDIT turn: {restored} file(s) restored, {removed} removed.': 'Proyecto restaurado a como estaba antes de la respuesta de @{agent} con «Puede editar»: {restored} archivo(s) restaurado(s), {removed} quitado(s).',
  'Incognito': 'Incógnito',
  'Chat': 'Conversar',
  'Edit': 'Editar',
  'Full access': 'Acceso total',
  '@{agent} asked for #3 again. With Copilot it edits without asking at every step, for as long as you choose.': '@{agent} volvió a pedir #3. Con Copiloto edita sin preguntarte a cada paso, por el tiempo que elijas.',
  'SEE COPILOT': 'VER COPILOTO',
  'Notice from MADRE': 'Aviso de MADRE',
  'Important notice from MADRE': 'Aviso importante de MADRE',
  'Security notice from MADRE': 'Aviso de seguridad de MADRE',
  'Read more': 'Leer más',
  'No such notice.': 'Ese aviso no existe.',
  'madre.run said: {error}': 'madre.run respondió: {error}',
  'madre.run did not answer.': 'madre.run no respondió.',
  'That is not a notice MADRE would show: check the words, the dates and the link.': 'Ese no es un aviso que MADRE mostraría: revisa el texto, las fechas y el enlace.',
  'Notices from MADRE': 'Avisos de MADRE',
  'What MADRE\'s author tells every copy: a new version, a fix, a service stop. Nothing about you is sent to receive them. Security notices always show.': 'Lo que el autor de MADRE avisa a todas las copias: una versión nueva, un arreglo, un servicio que se detiene. Para recibirlos no se envía nada de ti. Los avisos de seguridad se muestran siempre.',
  'Notices to every copy': 'Avisos a todas las copias',
  'Write a notice that every copy of MADRE shows, with or without diagnostics: signed on this computer, read from madre.run. Only you see this.': 'Escribe un aviso que muestran todas las copias de MADRE, con o sin diagnóstico: se firma en esta computadora y se lee de madre.run. Solo tú lo ves.',
  'Information': 'Información',
  'Important': 'Importante',
